mapper.select:
SELECT * FROM com_delivery_scope_detail WHERE tenant_id = #{tenantId} AND deleted = b'0' AND delivery_scope_id IN
#{scopeId}
ORDER BY delivery_scope_id, id FOR UPDATE

mapper.update:
UPDATE com_delivery_scope
SET scope_status = 'RELEASED', effective_to = #{effectiveTo}, version = version + 1,
    updater = '0', update_time = #{updateTime}
WHERE tenant_id = #{tenantId} AND id = #{scopeId} AND version = #{expectedVersion}
  AND scope_status = 'ACTIVE' AND effective_to IS NULL AND deleted = b'0'
